"use client";

import * as React from "react";
import ReactMarkdown from "react-markdown";
import rehypeRaw from "rehype-raw";
import rehypeSanitize, { defaultSchema } from "rehype-sanitize";
import remarkGfm from "remark-gfm";
import { InlineCitation } from "../inline-citation/inline-citation.js";
import { Reasoning } from "../reasoning/reasoning.js";
import { Sources, type SourceRef } from "../sources/sources.js";
import { ToolCall } from "../tool-call/tool-call.js";
import type { ToolCallState } from "../types.js";
import { cn } from "../../lib/utils.js";
import { closeUnterminated } from "./close-unterminated.js";
import { remarkAdmonitions } from "./remark-admonitions.js";

/**
 * Streaming-safe markdown renderer with AI-aware element slots.
 *
 * Native pipeline (no `streamdown`): `react-markdown` + `remark-gfm`
 * for tables/task lists, `rehype-raw` to preserve the custom
 * `<tool-call>` element, `rehype-sanitize` to whitelist our slot tags,
 * `closeUnterminated` for streaming recovery (closes mid-stream `**`,
 * fences, links, tags before the parser sees them).
 *
 * Slot wiring:
 * - **Fenced code** (` ```lang `) → `<pre><code class="language-*">` (client-safe; consumers post-highlight).
 * - **Footnote-style links** (`[1](url)`) → `<InlineCitation>` (inline `<sup>` with hover preview).
 * - **`<sources data='[…]' />`** → `<Sources>` (collapsible RAG-source list).
 * - **`<tool-call name=… state=… args=… result=…/>`** → `<ToolCall>`.
 * - **`> [!think]\n> body`** blockquotes → `<Reasoning>`.
 *
 * The fenced-code slot doesn't route to the in-house `<CodeBlock>`
 * because CodeBlock is an async Server Component and Markdown runs
 * client-side. Consumers in an RSC tree can compose `<CodeBlock>`
 * directly when they need server-side Shiki highlighting.
 *
 * @example
 * <Message role="assistant">
 *   <Markdown>{streamingText}</Markdown>
 * </Message>
 */
export interface MarkdownProps {
	/** Raw markdown. May be a partial chunk during streaming. */
	children: string;
	className?: string;
}

// Allowlist for the AI-aware slot tags + attrs. `hast-util-sanitize`
// normalizes element tag names to lowercase before lookup, so the
// `tool-call` and `sources` keys are the literal kebab-case HTML tag
// names. The `dataAdmonition` attribute key is the camelCase
// hast-property name — it serializes to the kebab `data-admonition`
// attribute on the rendered `<blockquote>`, which the
// `ReasoningOrQuoteSlot` reads as `rest["data-admonition"]`.
const SANITIZE_SCHEMA = {
	...defaultSchema,
	tagNames: [...(defaultSchema.tagNames ?? []), "tool-call", "sources"],
	attributes: {
		...(defaultSchema.attributes ?? {}),
		"tool-call": ["name", "state", "args", "result"],
		sources: ["data"],
		blockquote: [
			...((defaultSchema.attributes ?? {}).blockquote ?? []),
			["dataAdmonition"],
		],
	},
};

const COMPONENTS = {
	code: CodeBlockSlot,
	a: CitationOrLinkSlot,
	blockquote: ReasoningOrQuoteSlot,
	"tool-call": ToolCallSlot,
	sources: SourcesSlot,
} as const;

/**
 * Render streaming-safe markdown with AI-aware slot wiring.
 *
 * @param props - The markdown source string + optional className.
 * @returns A `<div>` wrapping the rendered markdown tree.
 */
function Markdown({ children, className }: MarkdownProps) {
	const safe = React.useMemo(() => closeUnterminated(children), [children]);
	return (
		<div
			className={cn(
				"prose prose-sm max-w-none text-foreground",
				"prose-headings:text-foreground prose-strong:text-foreground",
				"prose-a:text-primary prose-a:underline-offset-4 hover:prose-a:underline",
				"prose-code:text-foreground prose-code:before:content-none prose-code:after:content-none",
				className,
			)}
		>
			{/*
			 * SECURITY INVARIANT: rehype-sanitize MUST follow rehype-raw.
			 * Reordering re-opens raw <script>/<iframe>/event-handler
			 * injection from any markdown source — including streamed model
			 * output, where an attacker could prompt-inject arbitrary HTML.
			 * The sanitize schema's `tagNames` allowlist is the only line
			 * of defense once raw HTML is parsed.
			 */}
			<ReactMarkdown
				remarkPlugins={[remarkGfm, remarkAdmonitions]}
				rehypePlugins={[rehypeRaw, [rehypeSanitize, SANITIZE_SCHEMA]]}
				components={COMPONENTS}
			>
				{safe}
			</ReactMarkdown>
		</div>
	);
}

export { Markdown, closeUnterminated };

// ─── Slot renderers ────────────────────────────────────────────────────
//
// Inlined into this file (rather than imported from a `slots/`
// subdirectory) so the registry-build distribution path ships a single
// self-contained `markdown.tsx`. The npm-published `@hex-core/components`
// has tsup inline imports anyway; the CLI distribution path
// (`npx hex add markdown`) only walks one file deep, so nested slots
// would break consumer compiles.

// In markdown, `[1](url)` parses as a link whose TEXT is "1" — the
// brackets are syntax, not content. So a "footnote-style" link is one
// whose visible text is a bare integer.
const FOOTNOTE_RE = /^(\d+)$/;

interface CitationLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
	/** Hast node passed by react-markdown@10 — destructured to keep it off the DOM. */
	node?: unknown;
}

/**
 * `react-markdown` `a` renderer. Footnote-style numeric links become
 * `<InlineCitation>` (inline `<sup>` + hover preview); everything else
 * renders as a default link with prose styling.
 *
 * The block-level `<Citation>` chip is still importable separately —
 * use it inside a `<Sources>` panel where the chip-shaped UI fits, and
 * use this slot for inline mid-sentence references.
 *
 * @param props - Anchor attributes + react-markdown's hast `node` (dropped).
 * @returns Either an `<InlineCitation>` or an `<a>`.
 */
function CitationOrLinkSlot({
	href,
	children,
	className,
	node: _node,
	...rest
}: CitationLinkProps) {
	const text = extractText(children);
	const footnote = FOOTNOTE_RE.exec(text);
	if (footnote && href) {
		const index = Number(footnote[1]);
		return <InlineCitation index={index} url={href} title={inferCitationTitle(href)} />;
	}
	return (
		<a href={href} className={className} {...rest}>
			{children}
		</a>
	);
}

/**
 * Flatten a React-children value to a string for footnote-pattern
 * matching. Footnote links from `react-markdown` come through as a
 * single string child (`<a>1</a>`), so we only need string + array
 * unwrapping; nested elements correctly fall through to a default
 * `<a>` since their text doesn't match `^\d+$` anyway.
 *
 * @param children - The link's React children.
 * @returns The flattened text content (empty for non-string trees).
 */
function extractText(children: React.ReactNode): string {
	if (typeof children === "string") return children;
	if (Array.isArray(children)) return children.map(extractText).join("");
	return "";
}

/**
 * Pick a Citation title from the URL: hostname for absolute URLs,
 * the raw href for relative paths or anchors. Empty hostnames (e.g.
 * `mailto:foo@bar`) fall back to the href so the chip never renders
 * with an empty title.
 */
function inferCitationTitle(href: string): string {
	try {
		const url = new URL(href);
		const hostname = url.hostname.replace(/^www\./, "");
		return hostname.length > 0 ? hostname : href;
	} catch {
		return href;
	}
}

interface CodeBlockSlotProps extends React.HTMLAttributes<HTMLElement> {
	/** Hast node from react-markdown@10 — used to discriminate fenced vs inline. */
	node?: unknown;
}

/**
 * `react-markdown` `code` renderer.
 *
 * - **Block (fenced):** renders `<code class="language-*" data-fenced>`
 *   inside a `<pre>` wrapper that react-markdown adds. We tag the
 *   className so consumer-side highlighters can target it.
 * - **Inline:** plain `<code>` with token + muted-bg styling.
 *
 * Detects fenced via `language-*` className OR newline in children
 * (the parser only emits multi-line content for fenced blocks, never
 * for inline code). react-markdown@10 dropped the `inline` prop, so
 * we don't rely on it.
 *
 * @param props - HTML attributes + react-markdown's hast `node` (dropped).
 * @returns A `<code>` element.
 */
function CodeBlockSlot({ className, children, node: _node, ...rest }: CodeBlockSlotProps) {
	const langMatch = /language-([a-zA-Z0-9-]+)/.exec(className ?? "");
	const isFenced = Boolean(langMatch) || String(children ?? "").includes("\n");

	if (!isFenced) {
		return (
			<code
				className={cn(
					"rounded bg-muted px-[0.3em] py-[0.15em] font-mono text-[0.85em]",
					className,
				)}
				{...rest}
			>
				{children}
			</code>
		);
	}

	return (
		<code
			className={cn("font-mono text-sm", className)}
			data-fenced="true"
			{...rest}
		>
			{children}
		</code>
	);
}

interface ReasoningSlotProps extends React.BlockquoteHTMLAttributes<HTMLQuoteElement> {
	"data-admonition"?: string;
	/** Hast node from react-markdown@10 — destructured to keep it off the DOM. */
	node?: unknown;
}

/**
 * `react-markdown` `blockquote` renderer. Routes `[!think]` admonitions
 * to `<Reasoning>` (tagged via the `remarkAdmonitions` mdast plugin);
 * everything else renders as a styled blockquote.
 *
 * @param props - Blockquote attributes + react-markdown's hast `node` (dropped).
 * @returns Either a `<Reasoning>` or a default `<blockquote>`.
 */
function ReasoningOrQuoteSlot({
	children,
	className,
	node: _node,
	...rest
}: ReasoningSlotProps) {
	if (rest["data-admonition"] === "think") {
		return <Reasoning>{children}</Reasoning>;
	}
	return (
		<blockquote
			className={cn(
				"my-4 border-l-2 border-border pl-4 italic text-muted-foreground",
				className,
			)}
			{...rest}
		>
			{children}
		</blockquote>
	);
}

interface ToolCallAttrs {
	name?: string;
	state?: string;
	args?: string;
	result?: string;
	children?: React.ReactNode;
	/** Hast node from react-markdown@10 — destructured to keep it off the DOM. */
	node?: unknown;
}

const VALID_TOOL_CALL_STATES: Record<ToolCallState, true> = {
	pending: true,
	running: true,
	result: true,
	error: true,
};

/**
 * Renderer for the custom `<tool-call>` HTML tag (preserved by
 * `rehype-raw`, allowed in the sanitize schema). Reads `name`
 * (required), `state` (defaults to `result`), and JSON-stringified
 * `args` / `result` from the element attributes; renders `<ToolCall>`.
 * Falls back to passthrough if `name` is missing — keeps malformed
 * mid-stream fragments from crashing the render.
 *
 * @param props - Tool-call attributes + hast `node` (dropped).
 * @returns A `<ToolCall>` or a Fragment passthrough.
 */
function ToolCallSlot({ name, state, args, result, children, node: _node }: ToolCallAttrs) {
	if (!name) return <>{children}</>;
	const parsedState: ToolCallState = isToolCallState(state) ? state : "result";
	return (
		<ToolCall
			name={name}
			state={parsedState}
			args={parseJson(args)}
			result={parseJson(result)}
		/>
	);
}

function isToolCallState(value: unknown): value is ToolCallState {
	return typeof value === "string" && value in VALID_TOOL_CALL_STATES;
}

function parseJson(raw: string | undefined): unknown {
	if (raw === undefined || raw === "") return undefined;
	try {
		return JSON.parse(raw);
	} catch {
		return raw;
	}
}

interface SourcesSlotAttrs {
	/** JSON-stringified `SourceRef[]`. Parsed lazily. */
	data?: string;
	children?: React.ReactNode;
	/** Hast node from react-markdown@10 — destructured to keep it off the DOM. */
	node?: unknown;
}

/**
 * Renderer for the custom `<sources>` HTML tag (preserved by
 * `rehype-raw`, allowed in the sanitize schema).
 *
 * Reads a JSON-stringified `data` attribute holding a `SourceRef[]`
 * and renders `<Sources>`. Bad JSON, missing data, or a non-array
 * payload all fall through to a Fragment passthrough — keeps malformed
 * mid-stream fragments from crashing the render.
 *
 * @param props - The serialized `data` attribute + hast `node` (dropped).
 * @returns A `<Sources>` panel or a Fragment passthrough.
 */
function SourcesSlot({ data, children, node: _node }: SourcesSlotAttrs) {
	// Memoize the parse pass — every Markdown re-render (each streaming
	// token!) would otherwise re-parse the (potentially large) JSON
	// payload from scratch. Same pattern as `closeUnterminated` upstream.
	const sources = React.useMemo(() => parseSources(data), [data]);
	if (!sources) return <>{children}</>;
	return <Sources sources={sources} />;
}

function parseSources(raw: string | undefined): SourceRef[] | null {
	if (raw === undefined || raw === "") return null;
	let parsed: unknown;
	try {
		parsed = JSON.parse(raw);
	} catch {
		return null;
	}
	if (!Array.isArray(parsed)) return null;
	const result: SourceRef[] = [];
	for (const item of parsed) {
		if (!item || typeof item !== "object") continue;
		// `in`-narrowing keeps each property access typed as `unknown`,
		// so the typeof guards below narrow without an `as` cast.
		if (!("title" in item) || typeof item.title !== "string") continue;
		const ref: SourceRef = { title: item.title };
		if ("url" in item && typeof item.url === "string") ref.url = item.url;
		if ("page" in item && typeof item.page === "number") ref.page = item.page;
		if ("index" in item && typeof item.index === "number") ref.index = item.index;
		result.push(ref);
	}
	return result;
}

/**
 * Streaming-safe markdown pre-processor. Detects unterminated tokens at
 * end-of-input and appends synthetic closers so `react-markdown`'s
 * parser doesn't render half-tokens as raw text or throw.
 *
 * Used by the `Markdown` component when consumers stream LLM output
 * one chunk at a time. Pure function — no I/O, no React, no plugins —
 * so it's trivially unit-testable as a truth table.
 *
 * Order matters. We close in this priority:
 *   1. Fenced code blocks (` ``` `) — most disruptive if open.
 *   2. HTML tags (`<tag` without `>`) — would consume rest of stream as attribute.
 *   3. Link parentheses (`[text](url`) — `react-markdown` falls back to text on these.
 *   4. Link brackets (`[text` no `]`) — consumes potentially huge bodies.
 *   5. Inline backticks (`` ` ``) — small but visible.
 *   6. Strikethrough (`~~`) — GFM extension.
 *   7. Bold (`**`) — must close before single `*` so we don't double-count.
 *   8. Italic (`*`, `_`) — last (most ambiguous).
 *
 * For tokens 5–8 we operate over a mask-view that replaces fenced
 * regions with whitespace of the same length, so an unclosed `**`
 * inside ` ``` ` doesn't trigger a closer.
 */

/**
 * Pre-process raw markdown for the streaming-safe renderer.
 * @param input - Raw markdown string, possibly mid-stream.
 * @returns Input with synthetic closers appended for each open-at-EOF token.
 */
export function closeUnterminated(input: string): string {
	let working = input;
	const suffixes: string[] = [];

	// 1. Fenced code: count lines that are exactly ``` (allowing optional language tag on opener).
	if (hasUnclosedFence(working)) {
		suffixes.push("\n```\n");
		// Mask the open fence's content so steps 5–8 ignore it.
		working = maskOpenFence(working);
	}

	// Mask all CLOSED fenced regions for step 5–8 — the content inside
	// closed fences is not subject to inline-token rules either.
	const masked = maskClosedFences(working);

	// 2a. HTML comment at any position with no `-->` close — the comment
	//     would otherwise consume the rest of the stream as comment body.
	if (/<!--(?![\s\S]*-->)/.test(working)) {
		suffixes.push("-->");
	}
	// 2b. HTML tag at tail: `<tag` (with optional attrs) with no closing `>`.
	//     Skipped if a `<!--` already triggered the comment closer above
	//     (otherwise we'd add both `-->` and `>` for the same opener).
	else if (/<[a-zA-Z][^<>]*$/.test(working)) {
		suffixes.push(">");
	}

	// 3 + 4. Link parens / brackets at tail.
	//
	// `[^[\]]` instead of `[^\]]` for the bracket-content character class:
	// excluding `[` AND `]` makes the engine reject mid-class on a nested
	// `[`, so input like `[[[[[…` runs in O(n) instead of O(n²) (CodeQL
	// flags the looser `[^\]]*` form as polynomial). Same idea on the
	// paren clause: `[^()]` rejects nested `(` immediately.
	if (/\[[^[\]]*\]\([^()]*$/.test(working)) {
		suffixes.push(")");
	} else if (/\[[^[\]]*$/.test(working)) {
		suffixes.push("]");
	}

	// 5. Inline backticks per line (in masked view, so fences excluded).
	let backtickOdd = 0;
	for (const line of masked.split("\n")) {
		// Only count single backticks — fenced code is masked out, but
		// a line like `` `foo` `bar` `` is two pairs (count 4 = even).
		const count = (line.match(/`/g) ?? []).length;
		if (count % 2 === 1) backtickOdd++;
	}
	if (backtickOdd % 2 === 1) {
		suffixes.push("`");
	}

	// 6. Strikethrough — count `~~` markers (each pair brackets one
	//    strikethrough span; an odd count means an opener with no closer).
	const strikeMarkers = countOutsideMaskedFences(masked, /~~/g);
	if (strikeMarkers % 2 === 1) {
		suffixes.push("~~");
	}

	// 7. Bold. Walk the string and count `**` runs without consuming `***`
	// (which is bold + italic). A `**bold**` is two markers; `***both***`
	// is one `**` then one `*` then content then `*` then `**`.
	const { boldOdd, italicAsteriskOdd } = countBoldItalic(masked);
	if (boldOdd) suffixes.push("**");
	// 8. Italic. Asterisk first, then underscore.
	if (italicAsteriskOdd) suffixes.push("*");
	if (countUnderscoreItalic(masked) % 2 === 1) suffixes.push("_");

	if (suffixes.length === 0) return input;
	return input + suffixes.join("");
}

/**
 * A fence opener / closer is a line whose trim is exactly ``` or ```lang.
 * @param input - Raw markdown.
 * @returns True when there's an odd number of fence delimiter lines.
 */
function hasUnclosedFence(input: string): boolean {
	const fenceRe = /^[ \t]*```/gm;
	const matches = input.match(fenceRe);
	return matches !== null && matches.length % 2 === 1;
}

/**
 * Replace the open fence (its opener line + everything after) with
 * whitespace of equal length. The opener line itself is included so its
 * fence delimiter doesn't show up in the inline-backtick / bold counts.
 * Inline tokens inside an open fence don't apply.
 * @param input - Raw markdown with a possibly-unclosed trailing fence.
 * @returns The same string with the open fence + content masked to spaces.
 */
function maskOpenFence(input: string): string {
	const fenceRe = /^[ \t]*```/gm;
	const matches: RegExpExecArray[] = [];
	let m: RegExpExecArray | null;
	// biome-ignore lint/suspicious/noAssignInExpressions: standard regex iteration
	while ((m = fenceRe.exec(input)) !== null) {
		matches.push(m);
	}
	if (matches.length % 2 !== 1) return input;
	const lastOpener = matches[matches.length - 1];
	if (!lastOpener) return input;
	// Mask from the start of the fence line (lastOpener.index points at
	// the first ``` char) through end-of-input, preserving newlines.
	const start = lastOpener.index;
	return input.slice(0, start) + input.slice(start).replace(/[^\n]/g, " ");
}

/**
 * Replace whole closed fence pairs (opener line + content + closer line)
 * with whitespace, keeping newlines. Both delimiter lines are masked so
 * the inline-token counters don't see their backtick characters.
 * @param input - Raw markdown.
 * @returns The same string with paired fences masked to whitespace.
 */
function maskClosedFences(input: string): string {
	const fenceRe = /^[ \t]*```/gm;
	const indices: number[] = [];
	let m: RegExpExecArray | null;
	// biome-ignore lint/suspicious/noAssignInExpressions: standard regex iteration
	while ((m = fenceRe.exec(input)) !== null) {
		indices.push(m.index);
	}
	let out = input;
	const pairCount = Math.floor(indices.length / 2);
	for (let i = 0; i < pairCount; i++) {
		const openIdx = indices[i * 2];
		const closeIdx = indices[i * 2 + 1];
		if (openIdx === undefined || closeIdx === undefined) continue;
		// Mask from the opener-line start through the closer-line end so
		// no `` ``` `` survives in the masked view.
		const closeEnd = out.indexOf("\n", closeIdx);
		const regionEnd = closeEnd < 0 ? out.length : closeEnd;
		const before = out.slice(0, openIdx);
		const region = out.slice(openIdx, regionEnd).replace(/[^\n]/g, " ");
		const after = out.slice(regionEnd);
		out = before + region + after;
	}
	return out;
}

/**
 * Count regex matches over the masked view.
 * @param masked - Markdown with closed/open fences masked to whitespace.
 * @param re - Pattern to count occurrences of.
 * @returns The number of matches.
 */
function countOutsideMaskedFences(masked: string, re: RegExp): number {
	const matches = masked.match(re);
	return matches?.length ?? 0;
}

/**
 * Count bold (double-asterisk) and asterisk-italic (single-asterisk)
 * markers, accounting for triple-asterisk which counts as one bold plus
 * one italic. Returns parity flags so callers can decide closers.
 * @param masked - Markdown with fences masked to whitespace.
 * @returns Parity flags for bold and asterisk-italic markers.
 */
function countBoldItalic(masked: string): { boldOdd: boolean; italicAsteriskOdd: boolean } {
	// Strip word-internal asterisks first (markdown ignores them) — be conservative.
	let bold = 0;
	let italic = 0;
	let i = 0;
	while (i < masked.length) {
		const ch = masked[i];
		if (ch !== "*") {
			i++;
			continue;
		}
		// Count run length of consecutive `*`.
		let run = 0;
		while (i + run < masked.length && masked[i + run] === "*") run++;
		// Decompose: every pair is one `**`, leftover single is `*`.
		bold += Math.floor(run / 2);
		italic += run % 2;
		i += run;
	}
	return { boldOdd: bold % 2 === 1, italicAsteriskOdd: italic % 2 === 1 };
}

/**
 * Count underscore italic markers. Markdown only treats `_foo_` as italic
 * when the underscores are at word boundaries — `foo_bar_baz` is plain
 * text. We approximate by only counting underscores where one side is
 * whitespace, line-start, or line-end.
 * @param masked - Markdown with fences masked to whitespace.
 * @returns The number of underscore markers eligible to act as italic.
 */
function countUnderscoreItalic(masked: string): number {
	let count = 0;
	for (let i = 0; i < masked.length; i++) {
		if (masked[i] !== "_") continue;
		const prev = i === 0 ? " " : masked[i - 1];
		const next = i === masked.length - 1 ? " " : masked[i + 1];
		const prevWs = prev === undefined || /[\s]/.test(prev);
		const nextWs = next === undefined || /[\s]/.test(next);
		if (prevWs || nextWs) count++;
	}
	return count;
}

import type { Blockquote, Paragraph, Root, Text } from "mdast";
import { visit } from "unist-util-visit";

/**
 * Tag blockquotes that start with `[!think]` as admonitions of type
 * `think`. Strips the marker text from the rendered content and writes
 * the type onto `node.data.hProperties` so the rehype pass surfaces it
 * as a `data-admonition` attribute on the `<blockquote>` element. Slot
 * renderers in the React layer then route that attribute to
 * `<Reasoning>`.
 *
 * Pure transform; no I/O. Operates on the mdast tree before
 * `remark-rehype` produces hast.
 *
 * Only ships `[!think]` in Phase 2. Other admonitions
 * (`[!warn]`/`[!info]`/`[!error]`) can be added by extending the
 * `SUPPORTED` set without touching slot wiring.
 *
 * @returns A unified plugin transformer.
 */
export function remarkAdmonitions() {
	return (tree: Root) => {
		visit(tree, "blockquote", (node: Blockquote) => {
			const marker = extractMarker(node);
			if (!marker || !SUPPORTED.has(marker.type)) return;
			stripMarkerText(node, marker.length);
			node.data = node.data ?? {};
			node.data.hProperties = {
				...(node.data.hProperties ?? {}),
				dataAdmonition: marker.type,
			};
		});
	};
}

const SUPPORTED = new Set(["think"]);

interface MarkerHit {
	type: string;
	/** Number of characters to strip from the leading text node. */
	length: number;
}

/**
 * Read the leading text of the first paragraph and detect a `[!type]`
 * marker. Returns null when the blockquote doesn't start with one.
 *
 * @param bq - The blockquote node to inspect.
 * @returns The matched admonition type + the marker length, or null.
 */
function extractMarker(bq: Blockquote): MarkerHit | null {
	const firstChild = bq.children[0];
	if (!firstChild || firstChild.type !== "paragraph") return null;
	const firstText = firstChild.children[0];
	if (!firstText || firstText.type !== "text") return null;
	const match = /^\[!([a-z]+)\]\s*\n?/.exec(firstText.value);
	if (!match) return null;
	const type = match[1];
	if (!type) return null;
	return { type, length: match[0].length };
}

/**
 * Remove the marker text from the leading text node so the rendered
 * blockquote shows only the body. If the text node becomes empty after
 * stripping, drop it.
 *
 * @param bq - The blockquote whose leading text needs trimming.
 * @param length - Number of characters to strip from the leading text.
 */
function stripMarkerText(bq: Blockquote, length: number): void {
	const firstChild: Paragraph | undefined = isParagraph(bq.children[0])
		? bq.children[0]
		: undefined;
	if (!firstChild) return;
	const firstText: Text | undefined = isText(firstChild.children[0])
		? firstChild.children[0]
		: undefined;
	if (!firstText) return;
	const stripped: Text = { ...firstText, value: firstText.value.slice(length) };
	if (stripped.value.length === 0) {
		firstChild.children.shift();
	} else {
		firstChild.children[0] = stripped;
	}
}

function isParagraph(node: Blockquote["children"][number] | undefined): node is Paragraph {
	return node?.type === "paragraph";
}

function isText(node: Paragraph["children"][number] | undefined): node is Text {
	return node?.type === "text";
}

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex UI: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}
